// App.tsx
import { BrowserRouter } from 'react-router-dom'
import { GlobalCss } from './styles'
import { useState, useEffect } from 'react'
import Rotas from './routes'

function App() {
  const [isModalOpen, setModalOpen] = useState(false)

  // Função para abrir o modal
  const openModal = () => setModalOpen(true)

  // Função para fechar o modal
  const closeModal = () => setModalOpen(false)

  // useEffect para bloquear/desbloquear a rolagem da página
  useEffect(() => {
    // Bloqueia a rolagem quando o modal está aberto
    if (isModalOpen) {
      document.body.style.overflow = 'hidden'
    } else {
      document.body.style.overflow = 'auto' // Restaura a rolagem quando o modal é fechado
    }

    // Limpeza ao desmontar o componente
    return () => {
      document.body.style.overflow = 'auto'
    }
  }, [isModalOpen])

  return (
    <BrowserRouter>
      <GlobalCss />
      <div className="container">
        <Rotas openModal={openModal} closeModal={closeModal} />
      </div>
    </BrowserRouter>
  )
}

export default App
